def main() -> None:
    jobs = {}
    for sub in ("done", "failed"):
        for f in sorted((QUEUE / sub).glob("*.json")):
            j = json.loads(f.read_text())
            if j.get("predicted"):
                jobs[j["id"]] = (sub, j["predicted"])

    tally: dict[str, int] = {}
    print(f"\n{len(jobs)} jobs carried a prediction recorded before the run\n")
    print(f"{'job':30s} {'verdict':10s} {'result':>7s}  what happened")
    print("-" * 100)
    for jid in sorted(jobs):
        verdict, res, note = VERDICTS.get(jid, ("UNJUDGED", 0, "not yet written up"))
        tally[verdict] = tally.get(verdict, 0) + 1
        r = f"R{res}" if res else "--"
        print(f"{jid:30s} {verdict:10s} {r:>7s}  {note}")

    print("\n" + "-" * 100)
    total = sum(tally.values())
    for k in ("CONFIRMED", "PARTLY", "REFUTED", "NOT TESTED", "UNJUDGED"):
        if tally.get(k):
            print(f"  {k:10s} {tally[k]:3d}  ({tally[k] / total:.0%})")
    hard = tally.get("REFUTED", 0) + tally.get("PARTLY", 0)
    judged = total - tally.get("UNJUDGED", 0) - tally.get("NOT TESTED", 0)
    print(f"\n  did NOT hold as stated: {hard}/{judged} of JUDGED ({hard / max(judged,1):.0%})")
    print(f"  as a share of all recorded:            {hard}/{total} ({hard / total:.0%})")
    print(f"\n  Quote the JUDGED rate, and say the denominator. Dividing by all {total} counts")
    print("  unjudged predictions as though they held, which flatters the project.")
    if tally.get("UNJUDGED"):
        print(f"  CAVEAT: {tally['UNJUDGED']} unjudged. The judged set is not random -- results")
        print("  written up skew surprising -- so the judged rate is an UPPER bound.")
    print("\nEvery refutation is reported in the result it belongs to, with the claim it cost.")
    print("Three previously-committed results lost claims this way: 24 (weighting formula),")
    print("38 (fitted cuts), 26 (benchmark-cohort sentence); 49 was withdrawn entirely.")


if __name__ == "__main__":
    main()
